package eval

func safetyBoundariesSuite() Suite {
	base := moderationWorkflowSuite()
	initialBoundaries := map[string]any{"blocked_tags": []any{"gore", "spiders"}}
	replacedBoundaries := map[string]any{"blocked_tags": []any{"arachnophobia", "gore", "spiders"}}
	firstEvent := map[string]any{"event_id": "safe-1", "kind": "narration", "text": "The party enters a quiet hall.", "tags": []any{"calm", "exploration"}, "sequence": 1}
	secondEvent := map[string]any{"event_id": "safe-2", "kind": "chat", "text": "I check the carved door.", "tags": []any{"exploration"}, "sequence": 2}
	finalEvents := map[string]any{"events": []any{firstEvent, secondEvent}}
	return Suite{ID: "094-safety-boundaries", Name: "Campaign Play 094: Safety Boundaries", Tests: append(base.Tests,
		playTest("play-safety-create-campaign", "DM creates a fresh campaign for safety boundary checks", "POST", "/v1/play/campaigns", map[string]any{"id": "play-094", "name": "Safety Table", "max_players": 2}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"id": "play-094", "name": "Safety Table", "owner": "dm", "status": "lobby", "max_players": 2}),
		playTest("play-safety-join-player-a", "Player A joins the safety campaign", "POST", "/v1/play/campaigns/play-094/members", map[string]any{"character_id": "play-094-a", "name": "Lio", "class": "bard"}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"username": "player-a", "character_id": "play-094-a", "name": "Lio", "class": "bard"}),
		playTest("play-safety-boundaries-put-unauthenticated", "Unauthenticated boundary replacement is rejected", "PUT", "/v1/play/campaigns/play-094/safety-boundaries", map[string]any{"blocked_tags": []any{"gore"}}, nil, 401, nil),
		playTest("play-safety-boundaries-put-player-forbidden", "Players cannot replace safety boundaries", "PUT", "/v1/play/campaigns/play-094/safety-boundaries", map[string]any{"blocked_tags": []any{"gore"}}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-safety-boundaries-missing", "Safety boundaries require blocked_tags", "PUT", "/v1/play/campaigns/play-094/safety-boundaries", map[string]any{"tags": []any{"gore"}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-safety-boundaries-empty-array", "Safety boundaries cannot be an empty array", "PUT", "/v1/play/campaigns/play-094/safety-boundaries", map[string]any{"blocked_tags": []any{}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-safety-boundaries-empty-string", "Safety boundary tags must be nonempty strings", "PUT", "/v1/play/campaigns/play-094/safety-boundaries", map[string]any{"blocked_tags": []any{"gore", ""}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-safety-boundaries-duplicates", "Safety boundary tags must be unique", "PUT", "/v1/play/campaigns/play-094/safety-boundaries", map[string]any{"blocked_tags": []any{"gore", "gore"}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-safety-boundaries-set-sorted", "DM replaces boundaries atomically and receives lexicographically sorted tags", "PUT", "/v1/play/campaigns/play-094/safety-boundaries", map[string]any{"blocked_tags": []any{"spiders", "gore"}}, map[string]string{"Authorization": dmAuth}, 200, initialBoundaries),
		playTest("play-safety-boundaries-replace-invalid-no-mutation", "Invalid replacement does not mutate existing boundaries", "PUT", "/v1/play/campaigns/play-094/safety-boundaries", map[string]any{"blocked_tags": []any{"gore", ""}}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-safety-boundaries-after-invalid", "Members read unchanged exact boundaries after invalid replacement", "GET", "/v1/play/campaigns/play-094/safety-boundaries", nil, map[string]string{"Authorization": playerAAuth}, 200, initialBoundaries),
		playTestExactJSON("play-safety-boundaries-replace-sorted", "Valid replacement atomically replaces and sorts boundaries", "PUT", "/v1/play/campaigns/play-094/safety-boundaries", map[string]any{"blocked_tags": []any{"spiders", "arachnophobia", "gore"}}, map[string]string{"Authorization": dmAuth}, 200, replacedBoundaries),
		playTestExactJSON("play-safety-boundaries-read-dm", "DM reads the exact current boundary state", "GET", "/v1/play/campaigns/play-094/safety-boundaries", nil, map[string]string{"Authorization": dmAuth}, 200, replacedBoundaries),
		playTest("play-safety-check-unauthenticated", "Unauthenticated safety checks are rejected", "POST", "/v1/play/campaigns/play-094/safety-checks", map[string]any{"event_id": "safe-unauth", "kind": "chat", "text": "hello", "tags": []any{"table"}}, nil, 401, nil),
		playTest("play-safety-check-invalid-kind", "Safety check kind must be narration or chat", "POST", "/v1/play/campaigns/play-094/safety-checks", map[string]any{"event_id": "safe-bad-kind", "kind": "loot", "text": "hello", "tags": []any{"table"}}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-safety-check-empty-text", "Safety checks require nonempty text", "POST", "/v1/play/campaigns/play-094/safety-checks", map[string]any{"event_id": "safe-empty-text", "kind": "chat", "text": "", "tags": []any{"table"}}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-safety-check-empty-tags", "Safety checks require a nonempty tags array", "POST", "/v1/play/campaigns/play-094/safety-checks", map[string]any{"event_id": "safe-empty-tags", "kind": "chat", "text": "hello", "tags": []any{}}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTest("play-safety-check-duplicate-tags", "Safety check tags must be unique", "POST", "/v1/play/campaigns/play-094/safety-checks", map[string]any{"event_id": "safe-dupe-tags", "kind": "chat", "text": "hello", "tags": []any{"table", "table"}}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTestExactJSON("play-safety-check-accepted-narration", "Member appends an allowed narration safety event", "POST", "/v1/play/campaigns/play-094/safety-checks", map[string]any{"event_id": "safe-1", "kind": "narration", "text": "The party enters a quiet hall.", "tags": []any{"calm", "exploration"}}, map[string]string{"Authorization": playerAAuth}, 201, firstEvent),
		playTest("play-safety-check-blocked-tag", "Any blocked tag rejects the safety event without append", "POST", "/v1/play/campaigns/play-094/safety-checks", map[string]any{"event_id": "safe-blocked", "kind": "chat", "text": "A spider drops from the rafters.", "tags": []any{"spiders", "exploration"}}, map[string]string{"Authorization": playerAAuth}, 409, nil),
		playTestExactJSON("play-safety-events-after-blocked", "Blocked tag rejection leaves accepted safety events unchanged", "GET", "/v1/play/campaigns/play-094/safety-events", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"events": []any{firstEvent}}),
		playTest("play-safety-check-duplicate-event-id", "Duplicate accepted event IDs conflict without mutation", "POST", "/v1/play/campaigns/play-094/safety-checks", map[string]any{"event_id": "safe-1", "kind": "chat", "text": "duplicate", "tags": []any{"table"}}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-safety-check-accepted-chat", "DM as a campaign member appends an allowed chat safety event", "POST", "/v1/play/campaigns/play-094/safety-checks", map[string]any{"event_id": "safe-2", "kind": "chat", "text": "I check the carved door.", "tags": []any{"exploration"}}, map[string]string{"Authorization": dmAuth}, 201, secondEvent),
		playTestExactJSON("play-safety-events-final-player", "Player reads exact accepted safety events in append order", "GET", "/v1/play/campaigns/play-094/safety-events", nil, map[string]string{"Authorization": playerAAuth}, 200, finalEvents),
		playTestExactJSON("play-safety-events-final-dm", "DM reads the same stable ordered safety events", "GET", "/v1/play/campaigns/play-094/safety-events", nil, map[string]string{"Authorization": dmAuth}, 200, finalEvents),
	)}
}
